{
  "criteria": [
    {
      "criterion": "claridad",
      "score": 3,
      "finding": "El requisito contiene una contradicción interna: 'generarse automáticamente' y 'solo cuando el gerente los solicite manualmente' son mutuamente excluyentes. El sistema no puede ser simultáneamente totalmente automático y depender de una solicitud manual para iniciar el proceso.",
      "recommendation": "Definir si la generación es automática programada o si el gerente inicia un proceso de reporte bajo demanda."
    },
    {
      "criterion": "especificidad",
      "score": 4,
      "finding": "Se especifica la frecuencia (diaria) y el actor (gerente), pero no qué datos concretos se consideran 'necesarios'. Queda abierto qué métricas, rangos de fechas o formatos deben incluirse.",
      "recommendation": "Enumerar explícitamente los campos o datos mínimos que deben incluirse en cada reporte."
    },
    {
      "criterion": "atomicidad",
      "score": 2,
      "finding": "El texto combina dos ideas independentes: la programación automática diaria y la condición de solicitud manual del gerente. Mezclan el modo de desencadenamiento con la frecuencia, lo que dificulta evaluarlos por separado.",
      "recommendation": "Separar el requisito en dos: uno que defina la generación automática programada y otro que defina la opción de solicitud manual bajo demanda."
    },
    {
      "criterion": "completitud",
      "score": 3,
      "finding": "Falta especificar los datos exactos que deben incluirse ('necesarios' es un término vago). No hay definición de formato, frecuencia exacta ni condiciones de error o fallback si la automatización falla.",
      "recommendation": "Definir los datos mínimos obligatorios y el formato de salida esperado."
    },
    {
      "criterion": "consistencia",
      "score": 3,
      "finding": "Contradicción entre la generación automática y la solicitud manual. Además, el contexto indica que los gerentes consultan reportes desde la web, lo cual choca con la idea de que los reportes 'deben generarse' solo bajo solicitud, sin clarificar si la web los muestra automáticamente o requiere una acción.",
      "recommendation": "Alinear el modo de desencadenamiento con el canal de consulta (web) y eliminar la contradicción entre automático y manual."
    },
    {
      "criterion": "factibilidad",
      "score": 6,
      "finding": "Técnicamente factible generar reportes diarios y permitir solicitudes manuales, pero la contradicción interna y la falta de definición de datos dificultan estimar el esfuerzo real.",
      "recommendation": "Clarificar el modelo de desencadenamiento antes de estimar la factibilidad técnica."
    },
    {
      "criterion": "verificabilidad",
      "score": 3,
      "finding": "No es posible verificar objetivamente el cumplimiento porque 'necesarios' no tiene criterio medible y la contradicción entre automático y manual genera dos escenarios de prueba distintos sin definir cuál es el esperado.",
      "recommendation": "Definir criterios de aceptación medibles (fechas, formatos, datos mínimos) y aclarar el modo de generación."
    },
    {
      "criterion": "trazabilidad",
      "score": 4,
      "finding": "No hay un identificador único ni una necesidad de origen explícita declarada en el requisito. El contexto indica que los gerentes consultan reportes desde la web, lo que permite asociar el requisito a una necesidad de usuario, pero el texto no lo vincula formalmente.",
      "recommendation": "Asignar un identificador único (p. ej., REQ-001) y enunciar la necesidad del usuario (p. ej., 'Como gerente, necesito un reporte diario automático...') para facilitar su trazabilidad."
    },
    {
      "criterion": "ausencia_ambiguedad",
      "score": 2,
      "finding": "Términos ambigüos: 'necesarios' (no define qué datos), 'automáticamente' (no especifica el mecanismo ni la hora del día), 'solicitar manualmente' (no define el canal ni el disparador exacto).",
      "recommendation": "Sustituir los términos vagos por valores o condiciones medibles."
    },
    {
      "criterion": "criterios_aceptacion",
      "score": 2,
      "finding": "No hay criterios de aceptación explícitos ni condiciones medibles para determinar cuándo el requisito está satisfecho. 'Cada día' y 'necesarios' no son verificables sin definiciones adicionales.",
      "recommendation": "Definir criterios de aceptación con estructura Dado/Cuando/Entonces, incluyendo datos específicos, horarios y formatos de salida."
    }
  ],
  "ambiguous_terms": [
    {
      "term": "necesarios",
      "reason": "no define qué datos o métricas se deben incluir en el reporte"
    },
    {
      "term": "automáticamente",
      "reason": "no especifica el mecanismo de disparo ni la hora del día"
    },
    {
      "term": "solicitar manualmente",
      "reason": "no define el canal, el disparador ni la acción exacta que realiza el gerente"
    }
  ],
  "is_compound": true,
  "missing_information": [
    "Definición de los datos o campos mínimos que deben incluirse en cada reporte",
    "Hora exacta o mecanismo de la generación automática diaria",
    "Canal y acción concreta para la solicitud manual del gerente",
    "Formato de salida esperado (JSON, PDF, CSV, etc.)"
  ],
  "clarification_questions": [
    "¿Los reportes se generan automáticamente a una hora fija cada día, o el gerente los inicia bajo demanda? Clarificar si es uno u otro escenario, o si ambos modos deben coexistir.",
    "¿Cuáles son los datos o campos mínimos que deben incluirse en los reportes de ventas? Solicitar una lista concreta de métricas, rangos de fechas y formatos.",
    "¿Cómo solicita el gerente el reporte manualmente? (p. ej., botón en la web, API, correo electrónico) y qué disparador activa esa acción."
  ],
  "summary": "El requisito presenta contradicción interna entre generación automática y solicitud manual, usa términos vagos ('necesarios', 'automáticamente', 'solicitar manualmente') y falta definición de datos concretos. Se recomienda separar el modo de desencadenamiento y especificar los campos obligatorios y formato de salida para lograr claridad y verificabilidad."
}
